<?php
namespace App\Http\Controllers;
use App\Models\User;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Hash;
class UserController extends Controller { public function index(){ $users=User::orderBy('name')->paginate(15); return view('users.index',compact('users')); } public function store(Request $request){$data=$request->validate(['name'=>'required|string|max:255','email'=>'required|email|max:255|unique:users,email','password'=>'required|min:8','role'=>'required|in:admin,operator,viewer']); User::create(['name'=>$data['name'],'email'=>$data['email'],'password'=>Hash::make($data['password']),'role'=>$data['role']]); return back()->with('success','Pengguna berhasil ditambahkan.');} public function update(Request $request, User $user){$data=$request->validate(['name'=>'required|string|max:255','role'=>'required|in:admin,operator,viewer','password'=>'nullable|min:8']); $user->name=$data['name'];$user->role=$data['role'];if(!empty($data['password']))$user->password=Hash::make($data['password']);$user->save();return back()->with('success','Pengguna berhasil diperbarui.');} public function destroy(User $user){if(auth()->id()===$user->id)return back()->withErrors(['user'=>'Akun yang sedang digunakan tidak dapat dihapus.']);$user->delete();return back()->with('success','Pengguna berhasil dihapus.');} }